CREATE OR REPLACE FUNCTION public.iig_adopt_retained_group(p_pin text, p_account uuid, p_evidence text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid=iig_private.verified_organiser();gid bigint;old_owner uuid;
BEGIN
 PERFORM iig_private.recent_signin();
 IF NOT EXISTS(SELECT 1 FROM iig_private.platform_owners WHERE user_id=uid) THEN RAISE EXCEPTION 'Platform owner required' USING ERRCODE='42501';END IF;
 IF (p_pin IS NULL OR p_pin NOT IN ('1010','1260','8759')) OR length(btrim(coalesce(p_evidence,'')))<10 THEN RAISE EXCEPTION 'Approved retained group and independent identity evidence required';END IF;
 PERFORM 1 FROM auth.users WHERE id=p_account AND email_confirmed_at IS NOT NULL AND email IS NOT NULL AND NOT coalesce(is_anonymous,false)
 AND (banned_until IS NULL OR banned_until<=now()) FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM iig_private.account_deletions WHERE user_id=p_account) THEN RAISE EXCEPTION 'Verified active account required';END IF;
 SELECT id INTO gid FROM public.tens_in_groups WHERE group_pin=p_pin;
 PERFORM pg_advisory_xact_lock(gid);
 IF EXISTS(SELECT 1 FROM iig_private.group_owners WHERE owner_id=p_account AND group_id<>gid) THEN RAISE EXCEPTION 'This account already organises another group';END IF;
 SELECT owner_id INTO old_owner FROM iig_private.group_owners WHERE group_id=gid FOR UPDATE;
 IF old_owner IS NOT NULL AND old_owner<>p_account THEN RAISE EXCEPTION 'Existing organiser cannot be replaced by adoption';END IF;
 PERFORM 1 FROM public.tens_in_groups WHERE id=gid FOR UPDATE;
 INSERT INTO iig_private.group_owners(group_id,owner_id,request_id,requested_name,revision)
 VALUES(gid,p_account,gen_random_uuid(),'Retained Group '||p_pin,0)
 ON CONFLICT(group_id) DO UPDATE SET owner_id=excluded.owner_id,invite_token=gen_random_uuid(),revision=iig_private.group_owners.revision+1;
 UPDATE iig_private.release_groups SET owner_departed_at=NULL WHERE group_id=gid;
 INSERT INTO iig_private.release_audit(group_id,actor_id,action,evidence) VALUES(gid,uid,'adopt',p_evidence);
END $function$

CREATE OR REPLACE FUNCTION public.iig_apply_verified_subscription(p_pin text, p_user_id uuid, p_original_id text, p_expires_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare gid bigint; owner_uid uuid;
begin
 -- Only the server-side Apple verifier may invoke this after verifying Apple's response.
 if p_original_id is null or length(p_original_id) not between 1 and 200 or p_expires_at is null or p_expires_at<=now() then raise exception 'Invalid verified subscription'; end if;
 select id into gid from public.tens_in_groups where group_pin=p_pin;
 select owner_id into owner_uid from iig_private.group_owners where group_id=gid for update;
 perform 1 from public.tens_in_groups where id=gid for update;
 if gid is null then raise exception 'Group not found'; end if;
 perform iig_private.release_access(gid);
 if owner_uid is null then raise exception 'Verified group organiser required' using errcode='42501'; end if;
 if owner_uid is not null and (p_user_id is distinct from owner_uid or not exists(select 1 from auth.users u where u.id=p_user_id and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false) and (u.banned_until is null or u.banned_until<=now())) or exists(select 1 from iig_private.account_deletions where user_id=p_user_id)) then raise exception 'Verified group organiser required' using errcode='42501'; end if;
 if owner_uid is not null and exists(select 1 from public.tens_in_groups where id=gid and status='suspended') then raise exception 'This group is suspended; contact I’m In Golf before renewal'; end if;
 insert into iig_private.subscription_bindings(original_transaction_id,group_id,expires_at) values(p_original_id,gid,p_expires_at)
 on conflict(original_transaction_id) do update set expires_at=greatest(iig_private.subscription_bindings.expires_at,excluded.expires_at),updated_at=now()
 where iig_private.subscription_bindings.group_id=excluded.group_id;
 if not found then raise exception 'This subscription is already linked to a different group'; end if;
 update public.tens_in_groups set plan_type='plus',paid_status='paid',renewal_date=greatest(renewal_date,(p_expires_at at time zone 'UTC')::date),status='active',updated_at=now() where id=gid;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.iig_claim_player_relink(p_pin text, p_token text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid=iig_private.verified_organiser();g record;grant_row iig_private.relink_grants;email text;existing text;gid bigint;
BEGIN
 PERFORM iig_private.recent_signin();
 SELECT groups.id INTO gid FROM public.tens_in_groups groups JOIN iig_private.group_owners o ON o.group_id=groups.id WHERE groups.group_pin=p_pin FOR UPDATE OF o;
 PERFORM iig_private.release_access(gid);PERFORM iig_private.check_group_access(p_pin);
 SELECT * INTO grant_row FROM iig_private.relink_grants WHERE token_hash=iig_closed_entry.token_hash(p_token) AND group_id=gid FOR UPDATE;
 SELECT lower(btrim(u.email)) INTO email FROM auth.users u WHERE u.id=uid;
 IF (p_pin IS NULL OR p_pin NOT IN ('1010','1260','8759')) OR NOT FOUND OR grant_row.token_hash IS NULL OR grant_row.revoked
 OR grant_row.expires_at<=now() OR grant_row.email_hash IS DISTINCT FROM iig_closed_entry.token_hash(email)
 OR (grant_row.used_by IS NOT NULL AND grant_row.used_by<>uid) THEN RAISE EXCEPTION 'Reconnection link is invalid or expired' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.tens_in_groups groups WHERE groups.id=gid AND
 (SELECT count(*) FROM jsonb_array_elements(groups.state->'players') p WHERE p->>'id'=grant_row.player_id)=1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original player is missing or ambiguous';END IF;
 SELECT l.player_id INTO existing FROM iig_private.player_links l WHERE l.group_id=gid AND l.user_id=uid;
 IF (existing IS NOT NULL AND existing<>grant_row.player_id)
 OR EXISTS(SELECT 1 FROM iig_private.group_members m WHERE m.group_id=gid AND (m.user_id=uid OR m.player_id::text=grant_row.player_id)) THEN RAISE EXCEPTION 'An account or player is already connected';END IF;
 INSERT INTO iig_private.player_links VALUES(gid,uid,grant_row.player_id) ON CONFLICT(group_id,user_id) DO NOTHING;
 UPDATE iig_private.relink_grants SET used_by=uid WHERE token_hash=grant_row.token_hash;
 INSERT INTO iig_private.release_audit(group_id,actor_id,action,evidence) VALUES(gid,uid,'claim-player-relink','Verified email and owner-approved existing player ID');
 RETURN grant_row.player_id;
END $function$

CREATE OR REPLACE FUNCTION iig_closed_entry.lock_authenticated(p_pin text, p_revision bigint, p_authority text, p_invite uuid DEFAULT NULL::uuid)
 RETURNS TABLE(group_id bigint, revision bigint, player_id uuid, state jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid;o iig_private.group_owners;g public.tens_in_groups;pid uuid;
BEGIN
 IF p_authority IS NULL OR p_authority NOT IN ('owner','member','join') THEN RAISE EXCEPTION 'INVALID_AUTHORITY';END IF;
 IF p_authority='member' THEN
  -- Saved TEST member authority is the authenticated account-to-player mapping,
  -- not the organiser registration policy. Auth still validates the session;
  -- this RPC adds no email/anonymous/ban-status requirement to membership.
  uid:=auth.uid();
  IF uid IS NULL THEN RAISE EXCEPTION 'Member sign-in required' USING ERRCODE='42501';END IF;
  PERFORM 1 FROM auth.users WHERE id=uid FOR UPDATE;
  IF NOT FOUND OR EXISTS(SELECT 1 FROM iig_private.account_deletions WHERE user_id=uid)
  THEN RAISE EXCEPTION 'Member sign-in required' USING ERRCODE='42501';END IF;
 ELSE uid:=iig_private.verified_organiser();END IF;
 SELECT owners.* INTO o FROM iig_private.group_owners owners JOIN public.tens_in_groups groups ON groups.id=owners.group_id
 WHERE groups.group_pin=p_pin FOR UPDATE OF owners;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group membership required' USING ERRCODE='42501';END IF;
 IF p_authority='owner' AND o.owner_id IS DISTINCT FROM uid THEN RAISE EXCEPTION 'Organiser access required' USING ERRCODE='42501';END IF;
 IF p_authority='join' AND (p_invite IS NULL OR o.invite_token IS DISTINCT FROM p_invite) THEN RAISE EXCEPTION 'Invitation is invalid' USING ERRCODE='42501';END IF;
 SELECT m.player_id INTO pid FROM iig_private.group_members m WHERE m.group_id=o.group_id AND m.user_id=uid FOR SHARE;
 IF p_authority='member' AND pid IS NULL THEN RAISE EXCEPTION 'Group membership required' USING ERRCODE='42501';END IF;
 PERFORM iig_private.check_group_access(p_pin);
 IF p_authority<>'join' AND (p_revision IS NULL OR p_revision<>o.revision) THEN RAISE EXCEPTION 'Group changed; reload before saving' USING ERRCODE='40001';END IF;
 SELECT * INTO g FROM public.tens_in_groups WHERE id=o.group_id AND group_pin=p_pin FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group changed; reload before saving' USING ERRCODE='40001';END IF;
 IF p_authority<>'owner' AND pid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.state->'players') p WHERE p->>'id'=pid::text)
 THEN RAISE EXCEPTION 'Player no longer in group' USING ERRCODE='42501';END IF;
 RETURN QUERY SELECT o.group_id,o.revision,pid,g.state;
END $function$

CREATE OR REPLACE FUNCTION iig_closed_entry.write_authenticated(gid bigint, rev bigint, op text, s jsonb, actor text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE old_s jsonb;r iig_closed_entry.rounds;next_rev bigint;affected bigint;
BEGIN
 PERFORM 1 FROM iig_private.group_owners WHERE group_id=gid AND revision=rev FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group changed; reload before saving' USING ERRCODE='40001';END IF;
 SELECT state INTO old_s FROM public.tens_in_groups WHERE id=gid FOR UPDATE;
 IF op NOT IN ('member_attendance','member_score') AND
  (s IS NULL OR jsonb_typeof(s)<>'object' OR jsonb_typeof(s->'players') IS DISTINCT FROM 'array'
  OR jsonb_typeof(s->'history') IS DISTINCT FROM 'array' OR s ?| ARRAY['adminPin','adminSetupToken'] OR octet_length(s::text)>1048576)
 THEN RAISE EXCEPTION 'Invalid group state';END IF;
 PERFORM iig_closed_entry.initialise(gid::text,old_s);
 SELECT * INTO r FROM iig_closed_entry.rounds WHERE group_id=gid::text FOR UPDATE;
 IF op IN ('member_attendance','member_score') THEN
  IF r.phase<>'open' THEN RAISE EXCEPTION 'ROUND_NOT_OPEN';END IF;
  -- Validate even identical attendance requests, which do not run the row guard.
  -- The row guard repeats this exact field check before any changed state persists.
  PERFORM iig_closed_entry.validate_member_update(old_s,s,op,actor,r.closed,r.entrant_ids);
 END IF;
 INSERT INTO iig_closed_entry.permits VALUES(pg_backend_pid(),gid::text,pg_current_xact_id()::text,op,r.revision,iig_closed_entry.digest(s),true,actor)
 ON CONFLICT(backend,group_id) DO UPDATE SET transaction_id=excluded.transaction_id,operation=excluded.operation,
 expected_revision=excluded.expected_revision,state_digest=excluded.state_digest,available=true,actor_id=excluded.actor_id;
 UPDATE public.tens_in_groups SET state=s,updated_at=now() WHERE id=gid;
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected<>1 OR (SELECT state FROM public.tens_in_groups WHERE id=gid) IS DISTINCT FROM s
  OR (SELECT revision FROM iig_closed_entry.rounds WHERE group_id=gid::text)
   IS DISTINCT FROM (r.revision+CASE WHEN old_s IS DISTINCT FROM s THEN 1 ELSE 0 END)
  OR (old_s IS DISTINCT FROM s AND EXISTS(SELECT 1 FROM iig_closed_entry.permits WHERE backend=pg_backend_pid() AND group_id=gid::text AND available))
 THEN RAISE EXCEPTION 'AUTHENTICATED_WRITE_NOT_APPLIED';END IF;
 -- An identical-state update still runs the original hooks and increments the
 -- existing account revision, as before; never leave a usable no-op permit.
 UPDATE iig_closed_entry.permits SET available=false WHERE backend=pg_backend_pid() AND group_id=gid::text;
 UPDATE iig_private.group_owners SET revision=revision+1 WHERE group_id=gid RETURNING revision INTO next_rev;
 IF next_rev IS DISTINCT FROM rev+1 THEN RAISE EXCEPTION 'AUTHENTICATED_REVISION_NOT_APPLIED';END IF;
 RETURN next_rev;
END $function$

CREATE OR REPLACE FUNCTION public.iig_create_owned_group(p_name text, p_organiser_name text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := iig_private.verified_organiser();
  v_existing iig_private.group_owners%rowtype;
  v_pin text; v_id bigint; v_try integer; v_name text := btrim(p_name);
begin
  if not exists(select 1 from iig_private.registration_settings where singleton and enabled)
     and not exists(select 1 from iig_private.setup_testers where user_id=v_uid)
  then raise exception 'Registration is not open yet' using errcode='42501'; end if;
  if p_request_id is null or v_name is null or length(v_name) not between 1 and 80
    or p_organiser_name is null or length(btrim(p_organiser_name)) not between 1 and 80
  then raise exception 'Enter a group name and organiser name (1–80 characters)'; end if;
  -- Serialise requests by account, including requests with different idempotency keys.
  perform 1 from auth.users where id=v_uid for update;
  select * into v_existing from iig_private.group_owners where owner_id=v_uid;
  if found then
    if v_existing.request_id<>p_request_id or v_existing.requested_name<>v_name
    then raise exception 'This organiser already has a group'; end if;
    select group_pin into v_pin from public.tens_in_groups where id=v_existing.group_id;
    return jsonb_build_object('group_pin',v_pin,'group_id',v_existing.group_id);
  end if;
  for v_try in 1..100 loop
    v_pin := (1000+floor(random()*9000))::integer::text;
    IF v_pin IN ('1010','2026') THEN CONTINUE; END IF;
    begin
      -- Plus is included free for now; retain creation/notification hooks and unpaid metadata.
      insert into public.tens_in_groups(group_name,group_pin,state,admin_name,admin_contact,plan_type,trial_expiry_date)
      values(v_name,v_pin,jsonb_build_object('groupName',v_name,'course','','date','',
        'stake',0,'gameType','money','roundOpen',false,'pointsCompetition','stableford',
        'pointsValue',10,'players','[]'::jsonb,'history','[]'::jsonb),
        btrim(p_organiser_name),(select email from auth.users where id=v_uid),'complimentary',NULL) returning id into v_id;
      exit;
    exception when unique_violation then
      if not exists(select 1 from public.tens_in_groups where group_pin=v_pin) then raise; end if;
      v_id := null;
    end;
  end loop;
  if v_id is null then raise exception 'No group PIN available; try again'; end if;
  insert into iig_private.group_owners(group_id,owner_id,request_id,requested_name,pin_join_enabled)
  values(v_id,v_uid,p_request_id,v_name,true);
  return jsonb_build_object('group_pin',v_pin,'group_id',v_id);
end $function$

CREATE OR REPLACE FUNCTION public.iig_create_owned_playing_group(p_name text, p_organiser_name text, p_handicap numeric, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE created jsonb; owned jsonb; member jsonb; player_id text;
BEGIN
 IF p_handicap IS NULL OR p_handicap NOT BETWEEN -10 AND 60 OR p_handicap<>round(p_handicap,1) THEN
  RAISE EXCEPTION 'Enter your handicap from -10 to 60, with up to one decimal place.' USING ERRCODE='22023';
 END IF;
 -- The established writer verifies the account, registration policy and retry key.
 created:=public.iig_create_owned_group(p_name,p_organiser_name,p_request_id);
 owned:=public.iig_read_entry_group();
 IF owned IS NULL OR owned->>'group_pin' IS DISTINCT FROM created->>'group_pin' OR owned->>'invite_token' IS NULL THEN
  RAISE EXCEPTION 'Your new group could not be confirmed. Please try again.';
 END IF;
 -- Same verified membership operation used by the existing player setup. A retry
 -- returns the linked player instead of adding a duplicate. Both writes commit together.
 player_id:=public.iig_join_release_group(owned->>'group_pin',(owned->>'invite_token')::uuid,p_organiser_name,p_handicap);
 member:=public.iig_read_entry_group(owned->>'group_pin');
 IF player_id IS NULL OR member->>'player_id' IS DISTINCT FROM player_id
 OR (SELECT count(*) FROM jsonb_array_elements(member->'state'->'players') p WHERE p->>'id'=player_id)<>1 THEN
  RAISE EXCEPTION 'Your player profile could not be confirmed. Please try again.';
 END IF;
 RETURN created||jsonb_build_object('player_id',player_id);
END $function$

CREATE OR REPLACE FUNCTION public.iig_get_player_group(p_pin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_state jsonb; v_player uuid; v_out jsonb; v_revision bigint;
begin
  select g.state,m.player_id,o.revision into v_state,v_player,v_revision
    from public.tens_in_groups g join iig_private.group_owners o on o.group_id=g.id
    join iig_private.group_members m on m.group_id=g.id
    where g.group_pin=p_pin and m.user_id=auth.uid();
  if not found then raise exception 'Group membership required' using errcode='42501'; end if;
  perform iig_private.check_group_access(p_pin);
  -- Explicit projections: future admin-only fields cannot leak by default.
  select coalesce(jsonb_object_agg(key,value),'{}') into v_out from jsonb_each(v_state)
    where key=any(array['groupName','course','date','roundOpen','pointsCompetition','gameType']);
  return jsonb_build_object('state',v_out || jsonb_build_object('players',(
    select coalesce(jsonb_agg(jsonb_build_object('id',p->'id','name',p->'name','handicap',p->'handicap',
      'playingThisRound',p->'playingThisRound','stableford',p->'stableford','netScore',p->'netScore',
      'scoreSubmitted',p->'scoreSubmitted')),'[]') from jsonb_array_elements(v_state->'players') p)),
    'player_id',v_player,'revision',v_revision);
end $function$

CREATE OR REPLACE FUNCTION public.iig_get_player_join_options(p_pin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid=iig_private.verified_organiser();g record;
BEGIN
 IF p_pin IS NULL OR p_pin!~'^[0-9]{4}$' THEN RAISE EXCEPTION 'Enter your four-digit group PIN' USING ERRCODE='22023';END IF;
 SELECT t.id,t.group_pin,t.group_name,o.pin_join_enabled INTO g FROM public.tens_in_groups t JOIN iig_private.group_owners o ON o.group_id=t.id WHERE t.group_pin=p_pin;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group PIN not found' USING ERRCODE='42501';END IF;
 PERFORM iig_private.release_access(g.id);PERFORM iig_private.check_group_access(p_pin);
 RETURN jsonb_build_object('group_pin',g.group_pin,'group_name',g.group_name,'pin_join_enabled',g.pin_join_enabled);
END $function$

CREATE OR REPLACE FUNCTION public.iig_join_release_group(p_pin text, p_invite uuid, p_name text, p_handicap numeric)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid=iig_private.verified_organiser();pid text;gid bigint;server_invite uuid;pin_allowed boolean;s jsonb;
BEGIN
 IF p_pin IS NULL OR p_pin!~'^[0-9]{4}$' THEN RAISE EXCEPTION 'Enter your four-digit group PIN' USING ERRCODE='22023';END IF;
 SELECT o.group_id,o.invite_token,o.pin_join_enabled INTO gid,server_invite,pin_allowed
 FROM iig_private.group_owners o JOIN public.tens_in_groups g ON g.id=o.group_id WHERE g.group_pin=p_pin FOR UPDATE OF o;
 IF gid IS NULL THEN RAISE EXCEPTION 'Group PIN not found' USING ERRCODE='42501';END IF;
 PERFORM iig_private.release_access(gid);PERFORM iig_private.check_group_access(p_pin);
 SELECT state INTO s FROM public.tens_in_groups WHERE id=gid FOR UPDATE;
 SELECT m.player_id::text INTO pid FROM iig_private.group_members m WHERE m.group_id=gid AND m.user_id=uid;
 IF pid IS NULL THEN SELECT l.player_id INTO pid FROM iig_private.player_links l WHERE l.group_id=gid AND l.user_id=uid;END IF;
 IF pid IS NOT NULL THEN
  IF (SELECT count(*) FROM jsonb_array_elements(s->'players') p WHERE p->>'id'=pid)<>1 THEN RAISE EXCEPTION 'Player identity is missing or ambiguous' USING ERRCODE='42501';END IF;
  RETURN pid;
 END IF;
 IF p_pin='1010' THEN RAISE EXCEPTION 'Ask the organiser to reconnect your existing Group 1010 record' USING ERRCODE='42501';END IF;
 -- PIN policy supplies the existing internal join capability only for opted-in groups.
 -- An explicitly supplied invitation is still checked by the original writer.
 IF p_invite IS NULL AND pin_allowed THEN p_invite:=server_invite;END IF;
 RETURN public.iig_join_owned_group(p_pin,p_invite,p_name,p_handicap)::text;
END $function$

CREATE OR REPLACE FUNCTION public.iig_my_group_identity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid=iig_private.verified_organiser(); out jsonb;
begin
 select jsonb_build_object('group_pin',g.group_pin,'plan_type',g.plan_type) into out
 from public.tens_in_groups g join iig_private.group_owners o on o.group_id=g.id where o.owner_id=uid;
 if out is not null then perform iig_private.release_access((select group_id from iig_private.group_owners where owner_id=uid)); end if;
 return out;
end $function$

CREATE OR REPLACE FUNCTION public.iig_owner_delete_group(p_group_id text, p_pin text, p_confirmation text, p_fingerprint text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
AS $function$
DECLARE uid uuid:=iig_private.require_delete_owner(true); g public.tens_in_groups; snapshot jsonb; receipt iig_private.group_delete_receipts;
BEGIN
 IF p_pin IS NULL OR p_pin !~ '^[0-9]{4}$' OR p_group_id IS NULL OR p_group_id !~ '^[0-9]+$' OR p_request_id IS NULL
 OR p_confirmation IS DISTINCT FROM ('DELETE '||p_pin) OR p_fingerprint IS NULL OR p_fingerprint !~ '^[a-f0-9]{64}$'
 THEN RAISE EXCEPTION 'Confirm the selected group before deleting'; END IF;
 SELECT * INTO receipt FROM iig_private.group_delete_receipts WHERE request_id=p_request_id;
 IF FOUND THEN
  IF receipt.actor_id<>uid OR receipt.group_id::text<>p_group_id THEN RAISE EXCEPTION 'Deletion request does not match' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('deleted',true,'group_id',p_group_id,'request_id',p_request_id);
 END IF;
 IF p_pin IN ('1010','2026') THEN RAISE EXCEPTION 'This retained or demo group is protected.' USING ERRCODE='42501'; END IF;
 -- Match the existing authenticated-write lock order: owner row, group row, children.
 PERFORM 1 FROM iig_private.group_owners WHERE group_id::text=p_group_id FOR UPDATE;
 SELECT * INTO g FROM public.tens_in_groups WHERE id::text=p_group_id AND group_pin=p_pin FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group not found or changed; refresh the dashboard'; END IF;
 PERFORM 1 FROM public.iig_notification_settings x WHERE x.group_pin=g.group_pin FOR UPDATE;
PERFORM 1 FROM public.iig_push_subscriptions x WHERE x.group_pin=g.group_pin FOR UPDATE;
PERFORM 1 FROM public.iig_notification_events x WHERE x.group_pin=g.group_pin FOR UPDATE;
PERFORM 1 FROM iig_closed_entry.rounds x WHERE x.group_id=g.id::text FOR UPDATE;
PERFORM 1 FROM iig_closed_entry.credentials x WHERE x.group_id=g.id::text FOR UPDATE;
PERFORM 1 FROM iig_closed_entry.permits x WHERE x.group_id=g.id::text FOR UPDATE;
PERFORM 1 FROM iig_closed_entry.receipts x WHERE x.group_id=g.id::text FOR UPDATE;
PERFORM 1 FROM iig_closed_entry.archives x WHERE x.group_id=g.id::text FOR UPDATE;
PERFORM 1 FROM iig_closed_entry.member_credentials x WHERE x.group_id=g.id::text FOR UPDATE;
PERFORM 1 FROM iig_closed_entry.operation_audit x WHERE x.group_id=g.id::text FOR UPDATE;
PERFORM 1 FROM iig_closed_entry.identity_ids x WHERE x.group_id=g.id::text FOR UPDATE;
PERFORM 1 FROM iig_private.group_owners x WHERE x.group_id=g.id FOR UPDATE;
PERFORM 1 FROM iig_private.group_members x WHERE x.group_id=g.id FOR UPDATE;
PERFORM 1 FROM iig_private.release_groups x WHERE x.group_id=g.id FOR UPDATE;
PERFORM 1 FROM iig_private.player_links x WHERE x.group_id=g.id FOR UPDATE;
PERFORM 1 FROM iig_private.relink_grants x WHERE x.group_id=g.id FOR UPDATE;
PERFORM 1 FROM iig_private.release_audit x WHERE x.group_id=g.id FOR UPDATE;
PERFORM 1 FROM iig_private.subscription_bindings x WHERE x.group_id=g.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM iig_private.subscription_bindings WHERE group_id=g.id) THEN RAISE EXCEPTION 'This group has an Apple subscription record and cannot be deleted here.' USING ERRCODE='42501'; END IF;
 snapshot:=iig_private.group_delete_snapshot(g.id);
 IF encode(sha256(convert_to(snapshot::text,'UTF8')),'hex') IS DISTINCT FROM p_fingerprint THEN RAISE EXCEPTION 'Group changed; review its latest details before deleting' USING ERRCODE='40001'; END IF;
 INSERT INTO iig_private.group_delete_permits VALUES(pg_backend_pid(),pg_current_xact_id()::text,g.id,uid);
 DELETE FROM public.iig_notification_settings x WHERE x.group_pin=g.group_pin;
DELETE FROM public.iig_push_subscriptions x WHERE x.group_pin=g.group_pin;
DELETE FROM public.iig_notification_events x WHERE x.group_pin=g.group_pin;
DELETE FROM iig_closed_entry.rounds x WHERE x.group_id=g.id::text;
DELETE FROM iig_closed_entry.credentials x WHERE x.group_id=g.id::text;
DELETE FROM iig_closed_entry.permits x WHERE x.group_id=g.id::text;
DELETE FROM iig_closed_entry.receipts x WHERE x.group_id=g.id::text;
DELETE FROM iig_closed_entry.archives x WHERE x.group_id=g.id::text;
DELETE FROM iig_closed_entry.member_credentials x WHERE x.group_id=g.id::text;
DELETE FROM iig_closed_entry.operation_audit x WHERE x.group_id=g.id::text;
DELETE FROM iig_closed_entry.identity_ids x WHERE x.group_id=g.id::text;
DELETE FROM iig_private.group_members x WHERE x.group_id=g.id;
DELETE FROM iig_private.release_groups x WHERE x.group_id=g.id;
DELETE FROM iig_private.player_links x WHERE x.group_id=g.id;
DELETE FROM iig_private.relink_grants x WHERE x.group_id=g.id;
DELETE FROM iig_private.release_audit x WHERE x.group_id=g.id;
DELETE FROM iig_private.group_owners x WHERE x.group_id=g.id;
 DELETE FROM public.tens_in_groups WHERE id=g.id;
 IF EXISTS(SELECT 1 FROM public.tens_in_groups WHERE id=g.id) THEN RAISE EXCEPTION 'Group deletion could not be confirmed'; END IF;
 DELETE FROM iig_private.group_delete_permits WHERE backend=pg_backend_pid() AND transaction_id=pg_current_xact_id()::text AND group_id=g.id;
 -- Minimal operational receipt for safe retries: no group name, PIN, players or golf history.
 INSERT INTO iig_private.group_delete_receipts(request_id,actor_id,group_id) VALUES(p_request_id,uid,g.id);
 RETURN jsonb_build_object('deleted',true,'group_id',p_group_id,'request_id',p_request_id);
END $function$

CREATE OR REPLACE FUNCTION public.iig_owner_group_deletion_review(p_pin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid := iig_private.require_delete_owner(); g public.tens_in_groups; snapshot jsonb; reason text; fresh boolean:=true;
BEGIN
 IF p_pin IS NULL OR p_pin !~ '^[0-9]{4}$' THEN RAISE EXCEPTION 'Enter the four-digit group PIN'; END IF;
 SELECT * INTO STRICT g FROM public.tens_in_groups WHERE group_pin=p_pin;
 snapshot:=iig_private.group_delete_snapshot(g.id);
 IF p_pin IN ('1010','2026') THEN reason:='This retained or demo group is protected.';
 ELSIF EXISTS(SELECT 1 FROM iig_private.subscription_bindings WHERE group_id=g.id) THEN reason:='This group has an Apple subscription record and cannot be deleted here.'; END IF;
 BEGIN PERFORM iig_private.recent_signin(); EXCEPTION WHEN insufficient_privilege THEN fresh:=false; END;
 RETURN jsonb_build_object('group_id',g.id::text,'group_pin',g.group_pin,'group_name',g.group_name,
 'fingerprint',encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'),
 'can_delete',reason IS NULL,'blocked_reason',reason,'needs_verification',NOT fresh,
 'counts',jsonb_build_object(
 'players',jsonb_array_length(CASE WHEN jsonb_typeof(g.state->'players')='array' THEN g.state->'players' ELSE '[]'::jsonb END),
 'history_entries',jsonb_array_length(CASE WHEN jsonb_typeof(g.state->'history')='array' THEN g.state->'history' ELSE '[]'::jsonb END),
 'past_trips',jsonb_array_length(CASE WHEN jsonb_typeof(g.state#>'{trip,pastTrips}')='array' THEN g.state#>'{trip,pastTrips}' ELSE '[]'::jsonb END),
 'saved_snapshots',jsonb_array_length(snapshot->'iig_closed_entry.archives')+jsonb_array_length(snapshot->'iig_closed_entry.operation_audit'),
 'notifications',jsonb_array_length(snapshot->'public.iig_notification_events'),
 'linked_accounts',(SELECT count(DISTINCT id) FROM (SELECT owner_id id FROM iig_private.group_owners WHERE group_id=g.id UNION ALL SELECT user_id FROM iig_private.group_members WHERE group_id=g.id UNION ALL SELECT user_id FROM iig_private.player_links WHERE group_id=g.id) accounts)));
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Group not found';
END $function$

CREATE OR REPLACE FUNCTION public.iig_prepare_account_deletion()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid=auth.uid();o record;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM auth.users WHERE id=uid AND email_confirmed_at IS NOT NULL AND email IS NOT NULL AND NOT coalesce(is_anonymous,false)
 AND (banned_until IS NULL OR banned_until<=now()) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501';END IF;
 PERFORM iig_private.recent_signin();
 IF EXISTS(SELECT 1 FROM iig_private.platform_owners WHERE user_id=uid) THEN RAISE EXCEPTION 'Transfer platform administration before deleting this account';END IF;
 FOR o IN SELECT owners.group_id,g.group_pin FROM iig_private.group_owners owners JOIN public.tens_in_groups g ON g.id=owners.group_id WHERE owner_id=uid FOR UPDATE OF owners LOOP
  PERFORM 1 FROM public.tens_in_groups WHERE id=o.group_id FOR UPDATE;
  INSERT INTO iig_private.release_groups(group_id,owner_departed_at,retired_at,reason,changed_by)
  VALUES(o.group_id,now(),CASE WHEN o.group_pin IN ('1010','2026') THEN NULL ELSE now() END,'Organiser account deleted',uid)
  ON CONFLICT(group_id) DO UPDATE SET owner_departed_at=now(),retired_at=CASE WHEN o.group_pin IN ('1010','2026') THEN iig_private.release_groups.retired_at ELSE now() END,reason='Organiser account deleted',changed_by=uid,changed_at=now();
  UPDATE iig_private.group_owners SET owner_id=NULL,invite_token=gen_random_uuid(),revision=revision+1 WHERE group_id=o.group_id;
  UPDATE public.tens_in_groups SET admin_contact=NULL,admin_name=NULL WHERE id=o.group_id;
  UPDATE iig_closed_entry.credentials SET revoked=true WHERE group_id=o.group_id::text;
  UPDATE iig_closed_entry.member_credentials SET revoked=true WHERE group_id=o.group_id::text;
  UPDATE iig_closed_entry.permits SET available=false WHERE group_id=o.group_id::text;
 END LOOP;
 UPDATE iig_private.relink_grants SET revoked=true WHERE issued_by=uid OR used_by=uid OR email_hash=(SELECT iig_closed_entry.token_hash(lower(btrim(email))) FROM auth.users WHERE id=uid);
 UPDATE iig_closed_entry.member_credentials c SET revoked=true WHERE EXISTS(SELECT 1 FROM iig_private.player_links l WHERE l.user_id=uid AND l.group_id::text=c.group_id AND l.player_id=c.player_id)
 OR EXISTS(SELECT 1 FROM iig_private.group_members m WHERE m.user_id=uid AND m.group_id::text=c.group_id AND m.player_id::text=c.player_id);
 DELETE FROM iig_private.player_links WHERE user_id=uid;
 DELETE FROM iig_private.group_members WHERE user_id=uid;
 INSERT INTO iig_private.account_deletions(user_id) VALUES(uid) ON CONFLICT DO NOTHING;
 INSERT INTO iig_private.release_audit(actor_id,action,evidence) VALUES(uid,'prepare-account-deletion','Access revoked; canonical golf records retained; Auth deletion can retry');
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION iig_private.lock_release(p_pin text, p_revision bigint, p_authority text)
 RETURNS TABLE(group_id bigint, revision bigint, player_id text, state jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid=iig_private.verified_organiser();o iig_private.group_owners;g public.tens_in_groups;pid text;
BEGIN
 IF p_authority IS NULL OR p_authority NOT IN ('owner','member') THEN RAISE EXCEPTION 'Invalid authority';END IF;
 SELECT owners.* INTO o FROM iig_private.group_owners owners JOIN public.tens_in_groups groups ON groups.id=owners.group_id
 WHERE groups.group_pin=p_pin FOR UPDATE OF owners;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group membership required' USING ERRCODE='42501';END IF;
 PERFORM iig_private.release_access(o.group_id);
 IF p_authority='owner' AND o.owner_id IS DISTINCT FROM uid THEN RAISE EXCEPTION 'Organiser access required' USING ERRCODE='42501';END IF;
 SELECT m.player_id::text INTO pid FROM iig_private.group_members m WHERE m.group_id=o.group_id AND m.user_id=uid;
 IF pid IS NULL THEN SELECT l.player_id INTO pid FROM iig_private.player_links l WHERE l.group_id=o.group_id AND l.user_id=uid;END IF;
 IF p_authority='member' AND pid IS NULL THEN RAISE EXCEPTION 'Group membership required' USING ERRCODE='42501';END IF;
 PERFORM iig_private.check_group_access(p_pin);
 IF p_revision IS NOT NULL AND p_revision<>o.revision THEN RAISE EXCEPTION 'Group changed; reload before saving' USING ERRCODE='40001';END IF;
 SELECT * INTO g FROM public.tens_in_groups WHERE id=o.group_id FOR UPDATE;
 IF p_authority='member' AND (SELECT count(*) FROM jsonb_array_elements(g.state->'players') p WHERE p->>'id'=pid)<>1
 THEN RAISE EXCEPTION 'Player identity is missing or ambiguous' USING ERRCODE='42501';END IF;
 RETURN QUERY SELECT o.group_id,o.revision,pid,g.state;
END $function$

CREATE OR REPLACE FUNCTION public.iig_read_entry_group(p_pin text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid=iig_private.verified_organiser();g record;r iig_closed_entry.rounds;result jsonb;entry jsonb;pin text;
BEGIN
 IF p_pin IS NULL THEN
  SELECT groups.group_pin INTO pin FROM public.tens_in_groups groups JOIN iig_private.group_owners o ON o.group_id=groups.id WHERE o.owner_id=uid;
  IF pin IS NULL THEN RETURN NULL;END IF;
 ELSE pin:=p_pin;END IF;
 SELECT * INTO g FROM iig_private.lock_release(pin,NULL,CASE WHEN p_pin IS NULL THEN 'owner' ELSE 'member' END);
 IF p_pin IS NULL THEN
  result:=jsonb_build_object('group_pin',pin,'revision',g.revision,'state',g.state,'invite_token',
    (SELECT invite_token FROM iig_private.group_owners WHERE group_id=g.group_id));
 ELSE
  result:=jsonb_build_object('player_id',g.player_id,'revision',g.revision,'state',
   iig_closed_entry.member_view(g.state,g.player_id)||jsonb_build_object('sideGameDate',to_char(now() AT TIME ZONE 'Europe/London','YYYY-MM-DD')));
 END IF;
 SELECT * INTO r FROM iig_closed_entry.rounds WHERE group_id=g.group_id::text;
 IF FOUND THEN entry:=jsonb_build_object('open',r.phase='open','closed',r.closed,'entrantIds',r.entrant_ids);
 ELSE entry:=jsonb_build_object('open',iig_closed_entry.round_is_open(g.state),'closed',iig_closed_entry.has_score(g.state),'entrantIds',
  CASE WHEN iig_closed_entry.has_score(g.state) THEN (SELECT coalesce(jsonb_agg(p->'id'),'[]') FROM jsonb_array_elements(g.state->'players') p WHERE iig_closed_entry.eligible(g.state,p)) ELSE NULL END);END IF;
 RETURN result||jsonb_build_object('entry',entry,'plan_type',(SELECT plan_type FROM public.tens_in_groups WHERE id=g.group_id));
END $function$

CREATE OR REPLACE FUNCTION public.iig_set_group_retired(p_pin text, p_retired boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid=iig_private.verified_organiser();gid bigint;
BEGIN
 PERFORM iig_private.recent_signin();
 IF NOT EXISTS(SELECT 1 FROM iig_private.platform_owners WHERE user_id=uid) THEN RAISE EXCEPTION 'Platform owner required' USING ERRCODE='42501';END IF;
 IF p_pin IN ('1010','2026') OR p_retired IS NULL OR length(btrim(coalesce(p_reason,'')))<5 THEN RAISE EXCEPTION 'Retained groups are protected; a reason is required';END IF;
 SELECT o.group_id INTO gid FROM iig_private.group_owners o JOIN public.tens_in_groups g ON g.id=o.group_id WHERE g.group_pin=p_pin FOR UPDATE OF o;
 IF gid IS NULL THEN SELECT id INTO gid FROM public.tens_in_groups WHERE group_pin=p_pin;END IF;
 PERFORM 1 FROM public.tens_in_groups WHERE id=gid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group not found';END IF;
 INSERT INTO iig_private.release_groups(group_id,retired_at,reason,changed_by) VALUES(gid,CASE WHEN p_retired THEN now() ELSE NULL END,p_reason,uid)
 ON CONFLICT(group_id) DO UPDATE SET retired_at=excluded.retired_at,reason=excluded.reason,changed_by=uid,changed_at=now();
 INSERT INTO iig_private.release_audit(group_id,actor_id,action,evidence) VALUES(gid,uid,CASE WHEN p_retired THEN 'retire' ELSE 'restore' END,p_reason);
END $function$
